//      Useful as a coverage check: free-form fields can't be enum-validated;
//      in the demo they're things like POLICY identifiers, dates, dollar amounts.
MATCH (l:RecordLayout {name: "Premium Record Layout"})<-[:CONTAINED_IN]-(f:FieldRequirement)
WHERE NOT (f)-[:CODED_BY]->(:CodeList)
  AND NOT f.name STARTS WITH "SKIP"
RETURN f.position_start AS col, f.field_name AS field, f.format AS format
ORDER BY f.position_start

//      Today only one chain (B-0008-25 → A.34) — but as bulletins
//      accumulate this query shows the full edit history of any rule.
MATCH (newer)-[s:SUPERSEDES]->(older)
RETURN labels(newer)[1] AS type,
       older.name AS old, newer.name AS new,
       newer.effective_from AS new_effective_from

//      Should be EMPTY after cleanup. Anything here is an LLM-extraction
//      variant of a parser-owned name.
MATCH (l:RecordLayout)
WHERE NOT (l)<-[:CONTAINED_IN]-(:FieldRequirement)
  AND NOT (l)-[:REQUIRES]->(:FieldRequirement)
RETURN l.name AS phantom_layout

//      Should be EMPTY. Anything here was extracted by Sentinel without
//      a layout binding.
MATCH (f:FieldRequirement)
WHERE NOT (f)-[:CONTAINED_IN]->(:RecordLayout)
  AND NOT (:RecordLayout)-[:REQUIRES]->(f)
RETURN f.name AS orphan_field, f.position_start AS col

//      Should be EMPTY for parser-owned layouts. A few may exist on
//      LLM-extracted prose nodes.
MATCH (f:FieldRequirement)
WHERE f.position_start IS NULL
RETURN f.name, f.field_name LIMIT 25

//      "How do you know Cause-of-Loss code 26 means Named Storm Wind?"
//      Walks all the way from the value, through the codelist, to the
//      bulletin override that introduced it, to the bulletin's effective
//      date and the rule it cites.
MATCH (cv:CodeValue {code: "26"})
WHERE cv.name CONTAINS "Named Storm"
OPTIONAL MATCH (cl:CodeList)-[:HAS_VALUE]->(cv)
OPTIONAL MATCH (b:BulletinOverride)
  WHERE (b)-[:OVERRIDES]->(cl) OR (b)-[:OVERRIDES]->(:CodeValue)
OPTIONAL MATCH (cv)-[:CITES]->(rule:Rule)-[:CONTAINED_IN]->(d:RegulationDocument)
RETURN cv, cl, b, rule, d

//      Renders: bulletin → CodeList it overrides → before/after CodeValues.
//      The most visually punchy slide in Browser's graph view.
MATCH (b:BulletinOverride {name: "Named Storm Cause of Loss Reporting Override"})
OPTIONAL MATCH (b)-[o:OVERRIDES]->(target)
OPTIONAL MATCH (cl:CodeList {name: "Cause of Loss Code List"})-[:HAS_VALUE]->(cv:CodeValue)
RETURN b, o, target, cl, cv LIMIT 30
